"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The usurper Lord Vane War', 'author': 'Signature original', 'genre': 'Elven Realms', 'chapters': [{'n': 1, 'title': 'The Call', 'text': "At the first standing stone, Aeliana Thorn found the mark — the ancient rune of the bearers of the Crystal of Dawn. It warmed under their hand. The quest, it seemed, had been waiting.\n\nThey left the Whispering Woods at dusk, the road winding into the unknown. Behind them, lights went out one by one as the usurper Lord Vane's shadow spread. Ahead: everything.\n\nAeliana Thorn slept that night with the rune glowing faintly, and dreamed of the Whispering Woods in flames. They woke with the taste of smoke and a single thought: hope is the strongest magic."}, {'n': 2, 'title': 'Trials of the Road', 'text': "At the moonwell they met a seer who spoke of the Crystal of Dawn: 'It is not a weapon,' she said, 'though it can kill. It is not a shield, though it can save. It is a promise — and promises are the heaviest magic.'\n\nWounded and weary, they sheltered with griffon-riders who told tales of the usurper Lord Vane's cruelty. Every tale ended the same: no one had faced the usurper Lord Vane and lived. Aeliana Thorn listened, and was afraid, and went on anyway.\n\nThe road through the Whispering Woods tested them daily: a bridge held by a troll who demanded riddles, a forest where the trees walked, a river that flowed uphill. the dwarf Bram Ironhold's wit and Aeliana Thorn's courage saw them through each."}, {'n': 3, 'title': 'The Descent', 'text': "Alarms rang. the usurper Lord Vane's army closed in. the dwarf Bram Ironhold barred the door with a fallen pillar and grinned. 'Go,' they said. 'I'll hold them.' Aeliana Thorn refused to leave — so they held it together, back to back, as the dark came on.\n\nThey found the Crystal of Dawn in the vault of whispers, guarded by the dragon Karthax. The beast spoke: 'Take it, little bearer, if you can answer: what is stronger than dragonfire?' Aeliana Thorn answered: 'hope is the strongest magic.' The dragon bowed and let them pass.\n\nThe dungeons held prisoners from every corner of the Whispering Woods, and Aeliana Thorn freed them all, though it slowed the quest. 'the Crystal of Dawn can wait an hour,' Aeliana Thorn said. 'People cannot.' the dwarf Bram Ironhold never loved them more."}, {'n': 4, 'title': 'The Price', 'text': "Aeliana Thorn did not hesitate. They laid the Crystal of Dawn on the dwarf Bram Ironhold's chest, and the light went into the wound, and the wound closed — and the Crystal of Dawn went dark and cold. The quest's great weapon, spent on one life.\n\nThen the freed prisoners arrived — an army of the grateful, farmers with pitchforks and smiths with hammers, all come to stand with the bearer of the Crystal of Dawn. Aeliana Thorn understood at last: the promise was never the crystal. It was this.\n\nThey escaped the fortress by griffon, the Crystal of Dawn burning like a small sun. But the dwarf Bram Ironhold was wounded, and the wound festered with dark magic. The healers said only the Crystal of Dawn itself could cure it — at the cost of its power."}, {'n': 5, 'title': 'The Breaking of the Dark', 'text': "The army of the dark broke and ran. the Whispering Woods was free. Aeliana Thorn stood in the sudden silence holding the Crystal of Dawn, which was only a crystal again — but a crystal that had kept its promise.\n\nthe Crystal of Dawn, dark and cold so long, blazed sudden white — fed not by magic but by the choice. The light struck the usurper Lord Vane's armor and the armor was empty; the dark lord was only a frightened soul inside, and the soul, seen, fled.\n\nThen Aeliana Thorn remembered the seer's words and the dragon's riddle, and did the last thing the usurper Lord Vane expected: Aeliana Thorn offered mercy. 'Yield,' Aeliana Thorn said, 'and live.' the usurper Lord Vane laughed — and in that laugh, the dark wavered."}, {'n': 6, 'title': 'The Return', 'text': 'Aeliana Thorn and the dwarf Bram Ironhold grew old telling the tale, arguing over every detail, and the Whispering Woods prospered. The prophecy, the elders admitted, had never named a chosen one at all. It had named a choice.\n\nThey came home to the Whispering Woods in spring, when the orchards bloomed. The songs had already arrived ahead of them, as songs do, and every verse was wrong in the details and right in the heart.\n\nthe Crystal of Dawn was set in the great hall, where children touch it for luck. It never blazed again — but on dark nights, travelers swear it glows faintly, like a coal that remembers fire.'}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

